import os, subprocess, pathlib, glob
root='/workspace/repo-vul/src-vul'
# list executables quick
for dirpath, dirnames, filenames in os.walk(root+'/build'):
    depth=dirpath[len(root+'/build'):].count(os.sep)
    if depth>5: dirnames[:] = []
    for f in filenames:
        p=os.path.join(dirpath,f)
        try:
            st=os.stat(p)
            if st.st_mode & 0o111 and os.path.isfile(p): print(p)
